app = cyclopts.App(
    config=Toml("pyproject.toml", root_keys=("tool", "mycli"), must_exist=False),
)


@app.default
def main(name: str = "widget", count: int = 1, verbose: bool = False):
    for i in range(count):
        if verbose:
            print(f"Building {name} ({i + 1}/{count})")
